package com.example.complaintmanagement.controller; import com.example.complaintmanagement.dto.ComplaintDtos.AttachmentResponse; import com.example.complaintmanagement.entity.*; import com.example.complaintmanagement.repository.*; import org.springframework.web.bind.annotation.*; import java.time.LocalDateTime; import java.util.*; @RestController @RequestMapping("/api/complaints/{complaintId}/attachments") public class AttachmentController { final AttachmentRepository ar; final ComplaintRepository cr; public AttachmentController(AttachmentRepository a,ComplaintRepository c){ar=a;cr=c;} @GetMapping public List<AttachmentResponse> list(@PathVariable Long complaintId){return ar.findByComplaintIdOrderByUploadedAtDesc(complaintId).stream().map(x->new AttachmentResponse(x.getId(),x.getFileName(),x.getFileUrl(),x.getContentType(),x.getFileSize(),x.getUploadedAt().toString())).toList();} @PostMapping public AttachmentResponse metadata(@PathVariable Long complaintId,@RequestBody Map<String,Object> b){Complaint c=cr.findById(complaintId).orElseThrow();Attachment x=ar.save(Attachment.builder().complaint(c).fileName((String)b.getOrDefault("fileName","attachment")).fileUrl((String)b.getOrDefault("fileUrl","/uploads/placeholder")).contentType((String)b.getOrDefault("contentType","application/octet-stream")).fileSize(b.get("fileSize") instanceof Number n?n.longValue():0L).uploadedAt(LocalDateTime.now()).build());return new AttachmentResponse(x.getId(),x.getFileName(),x.getFileUrl(),x.getContentType(),x.getFileSize(),x.getUploadedAt().toString());}}